const TOKEN_ESPERADO = 'SamaraRental2026';
const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';
const token = authHeader.replace('Bearer ', '').trim();
if (TOKEN_ESPERADO && token !== TOKEN_ESPERADO) {
  throw new Error('401 - Token invalido');
}
return [{ json: $input.first().json.body }];

const payload = $input.first().json;
const GEMINI_KEY = 'AIzaSyBPzVNfWHzsXHUhNexVJjRSw9I3FW5R4yc';
const GEMINI_URL = 'https://generativelanguage.googleapis.com/v1/models/gemini-2.0-flash:generateContent?key=' + GEMINI_KEY;

// LOG: verificar payload
console.log('=== casaId ===', payload.casaId);
console.log('=== nombreArchivo ===', payload.nombreArchivo);
console.log('=== imagenMimeType ===', payload.imagenMimeType);
console.log('=== imagenBase64 length ===', payload.imagenBase64 ? payload.imagenBase64.length : 0);

if (!payload.imagenBase64) {
  throw new Error('imagenBase64 esta vacio o no llego en el payload');
}

// 1. Usar base64 enviado directamente desde la app (sin descarga HTTP)
const base64 = payload.imagenBase64;
const mimeType = payload.imagenMimeType || 'image/jpeg';

console.log('=== Base64 recibido OK, mimeType:', mimeType);

// 2. Prompt para Gemini
const tipo = payload.tipo || 'Ingreso';
const prompt = 'Eres un asistente experto en contabilidad. Analiza esta imagen de factura o comprobante de pago. El tipo de movimiento sugerido es: ' + tipo + '. Responde UNICAMENTE con JSON valido puro, sin bloques markdown, sin texto adicional. Estructura exacta: {"fecha": "YYYY-MM-DD", "monto": 12345.00, "descripcion": "descripcion breve", "categoria": "categoria especifica", "estado": "completo"}. Reglas: fecha en formato YYYY-MM-DD (null si no se ve), monto numero decimal positivo sin simbolos (null si no se ve), descripcion max 100 chars, categoria especifica como Electricidad/Agua/Internet/Renta/Mantenimiento/Seguro/Impuesto, estado completo solo si todos los campos estan presentes de lo contrario parcial.';

const geminiBody = {
  contents: [{
    parts: [
      { text: prompt },
      { inline_data: { mime_type: mimeType, data: base64 } }
    ]
  }],
  generationConfig: { temperature: 0.1, maxOutputTokens: 512 }
};

// 3. Llamar a Gemini
let geminiRawResponse;
try {
  geminiRawResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: GEMINI_URL,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(geminiBody),
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch(e) {
  throw new Error('Error HTTP al llamar Gemini: ' + e.message);
}

console.log('=== Gemini HTTP status:', geminiRawResponse.statusCode);
console.log('=== Gemini body snippet:', JSON.stringify(geminiRawResponse.body).substring(0, 300));

if (geminiRawResponse.statusCode !== 200) {
  const errBody = typeof geminiRawResponse.body === 'string' ? geminiRawResponse.body : JSON.stringify(geminiRawResponse.body);
  throw new Error('Gemini error ' + geminiRawResponse.statusCode + ': ' + errBody.substring(0, 400));
}

const geminiData = typeof geminiRawResponse.body === 'string' ? JSON.parse(geminiRawResponse.body) : geminiRawResponse.body;

// 4. Parsear respuesta
let resultado = { fecha: null, monto: null, descripcion: null, categoria: null, estado: 'parcial' };

try {
  const parts = geminiData && geminiData.candidates && geminiData.candidates[0] && geminiData.candidates[0].content && geminiData.candidates[0].content.parts;
  const text = parts && parts[0] ? parts[0].text : null;
  if (!text) throw new Error('Sin texto en respuesta de Gemini');

  let cleanText = text.trim();
  const m1 = cleanText.match(/```json\s*([\s\S]*?)\s*```/);
  const m2 = cleanText.match(/```\s*([\s\S]*?)\s*```/);
  const m3 = cleanText.match(/(\{[\s\S]*\})/);
  if (m1) cleanText = m1[1].trim();
  else if (m2) cleanText = m2[1].trim();
  else if (m3) cleanText = m3[1].trim();

  const parsed = JSON.parse(cleanText);

  let monto = null;
  if (parsed.monto != null) {
    monto = Math.abs(parseFloat(String(parsed.monto).replace(/[^0-9.]/g, '')));
    if (isNaN(monto)) monto = null;
  }

  let fecha = null;
  if (parsed.fecha) {
    const d = new Date(parsed.fecha);
    if (!isNaN(d.getTime())) fecha = d.toISOString().split('T')[0];
  }

  const completo = fecha && monto && parsed.descripcion && parsed.categoria;
  resultado = {
    fecha: fecha,
    monto: monto,
    descripcion: parsed.descripcion || null,
    categoria: parsed.categoria || null,
    estado: completo ? 'completo' : 'parcial'
  };
} catch (parseErr) {
  resultado.descripcion = 'Error de parseo: ' + parseErr.message.substring(0, 80);
}

return [{ json: resultado }];
